package sshpot

import (
	"bufio"
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net"
	"strconv"
	"strings"
	"sync"
	"time"
	"unicode"

	"Fishing/internal/model"
	"golang.org/x/crypto/ssh"
	"golang.org/x/term"
)

const (
	serverVersionBanner = "SSH-2.0-OpenSSH_8.9p1 Ubuntu-3ubuntu0.10"
	maxConcurrentConns  = 64
	handshakeTimeout    = 15 * time.Second
	sessionIdleTimeout  = 5 * time.Minute
	maxLoggedTextLen    = 4096
)

// LogFunc receives audit events generated by the SSH honeypot server.
type LogFunc func(model.LogEntry)

// Server emulates an SSH honeypot listening on a single TCP port.
type Server struct {
	hp       model.Honeypot
	bindHost string
	hostKey  ssh.Signer
	onLog    LogFunc

	listener net.Listener
	ctx      context.Context
	cancel   context.CancelFunc
	sem      chan struct{}
	wg       sync.WaitGroup

	connMu      sync.Mutex
	activeConns map[net.Conn]struct{}
	stopOnce    sync.Once
}

// New binds a TCP listener for the configured SSH honeypot.
func New(hp model.Honeypot, bindHost string, hostKey ssh.Signer, onLog LogFunc) (*Server, error) {
	if hostKey == nil {
		return nil, errors.New("host key is required")
	}
	if bindHost == "" {
		bindHost = "0.0.0.0"
	}

	addr := net.JoinHostPort(bindHost, strconv.Itoa(hp.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return nil, fmt.Errorf("listen %s: %w", addr, err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	return &Server{
		hp:          hp,
		bindHost:    bindHost,
		hostKey:     hostKey,
		onLog:       onLog,
		listener:    ln,
		ctx:         ctx,
		cancel:      cancel,
		sem:         make(chan struct{}, maxConcurrentConns),
		activeConns: make(map[net.Conn]struct{}),
	}, nil
}

// Addr returns the bound listener network address.
func (s *Server) Addr() net.Addr {
	return s.listener.Addr()
}

// Start begins accepting incoming SSH connections asynchronously.
func (s *Server) Start() {
	s.wg.Add(1)
	go s.acceptLoop()
}

// Stop closes the listener and all active connections, waiting for handlers to finish.
func (s *Server) Stop() {
	s.stopOnce.Do(func() {
		s.cancel()
		_ = s.listener.Close()

		s.connMu.Lock()
		for c := range s.activeConns {
			_ = c.Close()
		}
		s.connMu.Unlock()

		s.wg.Wait()
	})
}

func (s *Server) acceptLoop() {
	defer s.wg.Done()

	for {
		conn, err := s.listener.Accept()
		if err != nil {
			if s.ctx.Err() != nil || errors.Is(err, net.ErrClosed) {
				return
			}
			time.Sleep(50 * time.Millisecond)
			continue
		}

		select {
		case s.sem <- struct{}{}:
			s.wg.Add(1)
			go func(c net.Conn) {
				defer s.wg.Done()
				defer func() { <-s.sem }()
				s.handleConn(c)
			}(conn)
		default:
			_ = conn.Close()
		}
	}
}

func (s *Server) trackConn(c net.Conn) {
	s.connMu.Lock()
	s.activeConns[c] = struct{}{}
	s.connMu.Unlock()
}

func (s *Server) untrackConn(c net.Conn) {
	s.connMu.Lock()
	delete(s.activeConns, c)
	s.connMu.Unlock()
}

func (s *Server) handleConn(rawConn net.Conn) {
	s.trackConn(rawConn)
	defer func() {
		s.untrackConn(rawConn)
		_ = rawConn.Close()
	}()

	srcIP, srcPort := parseRemoteAddr(rawConn.RemoteAddr())
	connSessionID := randomHex(8)

	cfg := &ssh.ServerConfig{
		ServerVersion: serverVersionBanner,
		MaxAuthTries:  6,
		PasswordCallback: func(meta ssh.ConnMetadata, pass []byte) (*ssh.Permissions, error) {
			username := sanitizeText(meta.User(), 128)
			password := sanitizeText(string(pass), 256)
			clientVer := sanitizeText(string(meta.ClientVersion()), 128)

			userMatch := subtle.ConstantTimeCompare([]byte(meta.User()), []byte(s.hp.Username)) == 1
			passMatch := subtle.ConstantTimeCompare(pass, []byte(s.hp.Password)) == 1
			ok := userMatch && passMatch

			detail := "authentication rejected"
			if ok {
				detail = "authentication accepted"
			}

			s.emitLog(model.LogEntry{
				SessionID:     connSessionID,
				SourceIP:      srcIP,
				SourcePort:    srcPort,
				ClientVersion: clientVer,
				EventType:     model.EventAuthAttempt,
				Username:      username,
				Password:      password,
				AuthSuccess:   &ok,
				Detail:        detail,
			})

			if !ok {
				return nil, errors.New("permission denied")
			}

			return &ssh.Permissions{
				Extensions: map[string]string{
					"session_id": connSessionID,
					"username":   username,
				},
			}, nil
		},
	}
	cfg.AddHostKey(s.hostKey)

	_ = rawConn.SetDeadline(time.Now().Add(handshakeTimeout))
	sshConn, chans, reqs, err := ssh.NewServerConn(rawConn, cfg)
	if err != nil {
		return
	}
	_ = rawConn.SetDeadline(time.Time{})
	defer sshConn.Close()

	go ssh.DiscardRequests(reqs)

	clientVer := sanitizeText(string(sshConn.ClientVersion()), 128)
	username := sanitizeText(sshConn.User(), 128)
	sessionID := connSessionID
	if sshConn.Permissions != nil && sshConn.Permissions.Extensions["session_id"] != "" {
		sessionID = sshConn.Permissions.Extensions["session_id"]
	}

	for {
		select {
		case <-s.ctx.Done():
			return
		case newChan, ok := <-chans:
			if !ok {
				return
			}
			if newChan.ChannelType() != "session" {
				_ = newChan.Reject(ssh.Prohibited, "channel type disabled")
				continue
			}

			ch, chReqs, err := newChan.Accept()
			if err != nil {
				continue
			}

			s.wg.Add(1)
			go func() {
				defer s.wg.Done()
				s.handleSessionChannel(rawConn, ch, chReqs, sessionMeta{
					sessionID:     sessionID,
					username:      username,
					sourceIP:      srcIP,
					sourcePort:    srcPort,
					clientVersion: clientVer,
				})
			}()
		}
	}
}

type sessionMeta struct {
	sessionID     string
	username      string
	sourceIP      string
	sourcePort    int
	clientVersion string
}

type ptyConfig struct {
	hasPTY bool
	width  int
	height int
}

type execPayload struct {
	Command string
}

type subsystemPayload struct {
	Name string
}

type ptyReqPayload struct {
	Term        string
	Width       uint32
	Height      uint32
	PixelWidth  uint32
	PixelHeight uint32
	Modes       string
}

type windowChangePayload struct {
	Width       uint32
	Height      uint32
	PixelWidth  uint32
	PixelHeight uint32
}

func (s *Server) handleSessionChannel(rawConn net.Conn, ch ssh.Channel, reqs <-chan *ssh.Request, meta sessionMeta) {
	defer ch.Close()

	s.emitLog(model.LogEntry{
		SessionID:     meta.sessionID,
		SourceIP:      meta.sourceIP,
		SourcePort:    meta.sourcePort,
		ClientVersion: meta.clientVersion,
		EventType:     model.EventSessionOpen,
		Username:      meta.username,
		Detail:        "ssh session channel opened",
	})
	defer s.emitLog(model.LogEntry{
		SessionID:     meta.sessionID,
		SourceIP:      meta.sourceIP,
		SourcePort:    meta.sourcePort,
		ClientVersion: meta.clientVersion,
		EventType:     model.EventSessionClose,
		Username:      meta.username,
		Detail:        "ssh session channel closed",
	})

	pty := ptyConfig{width: 80, height: 24}
	winCh := make(chan [2]int, 4)
	shell := NewFakeShell(meta.username, meta.sourceIP)

	for {
		select {
		case <-s.ctx.Done():
			return
		case req, ok := <-reqs:
			if !ok {
				return
			}
			switch req.Type {
			case "pty-req":
				var p ptyReqPayload
				if err := ssh.Unmarshal(req.Payload, &p); err == nil {
					pty.hasPTY = true
					if p.Width > 0 && p.Width < 1000 {
						pty.width = int(p.Width)
					}
					if p.Height > 0 && p.Height < 1000 {
						pty.height = int(p.Height)
					}
				}
				if req.WantReply {
					_ = req.Reply(true, nil)
				}
			case "window-change":
				var w windowChangePayload
				if err := ssh.Unmarshal(req.Payload, &w); err == nil && w.Width > 0 && w.Height > 0 {
					select {
					case winCh <- [2]int{int(w.Width), int(w.Height)}:
					default:
					}
				}
				if req.WantReply {
					_ = req.Reply(true, nil)
				}
			case "env":
				if req.WantReply {
					_ = req.Reply(true, nil)
				}
			case "exec":
				var payload execPayload
				if err := ssh.Unmarshal(req.Payload, &payload); err != nil {
					if req.WantReply {
						_ = req.Reply(false, nil)
					}
					return
				}
				if req.WantReply {
					_ = req.Reply(true, nil)
				}

				cmd := sanitizeText(payload.Command, maxLoggedTextLen)
				if cmd != "" {
					s.emitLog(model.LogEntry{
						SessionID:     meta.sessionID,
						SourceIP:      meta.sourceIP,
						SourcePort:    meta.sourcePort,
						ClientVersion: meta.clientVersion,
						EventType:     model.EventCommand,
						Username:      meta.username,
						Command:       cmd,
						Detail:        "exec",
					})
				}

				out, code, _ := shell.Execute(payload.Command)
				if out != "" {
					if pty.hasPTY {
						out = strings.ReplaceAll(out, "\n", "\r\n")
					}
					_, _ = io.WriteString(ch, out)
				}
				sendExitStatus(ch, code)
				return
			case "shell":
				if req.WantReply {
					_ = req.Reply(true, nil)
				}
				s.runInteractiveShell(rawConn, ch, reqs, winCh, pty, shell, meta)
				return
			case "subsystem":
				var sub subsystemPayload
				_ = ssh.Unmarshal(req.Payload, &sub)
				s.emitLog(model.LogEntry{
					SessionID:     meta.sessionID,
					SourceIP:      meta.sourceIP,
					SourcePort:    meta.sourcePort,
					ClientVersion: meta.clientVersion,
					EventType:     model.EventCommand,
					Username:      meta.username,
					Command:       "subsystem:" + sanitizeText(sub.Name, 64),
					Detail:        "subsystem rejected",
				})
				if req.WantReply {
					_ = req.Reply(false, nil)
				}
			default:
				if req.WantReply {
					_ = req.Reply(false, nil)
				}
			}
		}
	}
}

func (s *Server) runInteractiveShell(
	rawConn net.Conn,
	ch ssh.Channel,
	reqs <-chan *ssh.Request,
	winCh <-chan [2]int,
	pty ptyConfig,
	shell *FakeShell,
	meta sessionMeta,
) {
	done := make(chan struct{})
	defer close(done)

	// Drain auxiliary channel requests (e.g. window-change) while shell runs.
	var terminal *term.Terminal
	if pty.hasPTY {
		terminal = term.NewTerminal(ch, shell.Prompt())
		_ = terminal.SetSize(pty.width, pty.height)
	}

	go func() {
		for {
			select {
			case <-done:
				return
			case <-s.ctx.Done():
				return
			case sz := <-winCh:
				if terminal != nil {
					_ = terminal.SetSize(sz[0], sz[1])
				}
			case req, ok := <-reqs:
				if !ok {
					return
				}
				if req.Type == "window-change" && terminal != nil {
					var w windowChangePayload
					if err := ssh.Unmarshal(req.Payload, &w); err == nil && w.Width > 0 && w.Height > 0 {
						_ = terminal.SetSize(int(w.Width), int(w.Height))
					}
				}
				if req.WantReply {
					_ = req.Reply(req.Type == "window-change", nil)
				}
			}
		}
	}()

	motd := "Welcome to Ubuntu 22.04.5 LTS (GNU/Linux 5.15.0-119-generic x86_64)\n\n" +
		" * Documentation:  https://help.ubuntu.com\n" +
		" * Management:     https://landscape.canonical.com\n" +
		" * Support:        https://ubuntu.com/pro\n\n" +
		"System information as of " + time.Now().UTC().Format("Mon Jan 02 15:04:05 UTC 2006") + "\n\n"

	if terminal != nil {
		_, _ = terminal.Write([]byte(motd))
		s.runPTYLoop(rawConn, ch, terminal, shell, meta)
		return
	}

	_, _ = io.WriteString(ch, motd)
	s.runLineLoop(rawConn, ch, shell, meta)
}

func (s *Server) runPTYLoop(rawConn net.Conn, ch ssh.Channel, terminal *term.Terminal, shell *FakeShell, meta sessionMeta) {
	for {
		_ = rawConn.SetReadDeadline(time.Now().Add(sessionIdleTimeout))
		line, err := terminal.ReadLine()
		_ = rawConn.SetReadDeadline(time.Time{})

		if err != nil {
			if errors.Is(err, io.EOF) {
				_, _ = terminal.Write([]byte("logout\n"))
				sendExitStatus(ch, 0)
				return
			}
			sendExitStatus(ch, 1)
			return
		}

		cmd := sanitizeText(line, maxLoggedTextLen)
		if cmd == "" {
			continue
		}

		s.emitLog(model.LogEntry{
			SessionID:     meta.sessionID,
			SourceIP:      meta.sourceIP,
			SourcePort:    meta.sourcePort,
			ClientVersion: meta.clientVersion,
			EventType:     model.EventCommand,
			Username:      meta.username,
			Command:       cmd,
			Detail:        "shell",
		})

		out, code, shouldExit := shell.Execute(line)
		if out != "" {
			_, _ = terminal.Write([]byte(out))
		}
		terminal.SetPrompt(shell.Prompt())
		if shouldExit {
			sendExitStatus(ch, code)
			return
		}
	}
}

func (s *Server) runLineLoop(rawConn net.Conn, ch ssh.Channel, shell *FakeShell, meta sessionMeta) {
	reader := bufio.NewReader(ch)
	for {
		_, _ = io.WriteString(ch, shell.Prompt())
		line, err := readLineAnyEOL(rawConn, reader, sessionIdleTimeout)

		trimmed := strings.TrimSpace(line)
		if trimmed != "" {
			cmd := sanitizeText(trimmed, maxLoggedTextLen)
			if cmd != "" {
				s.emitLog(model.LogEntry{
					SessionID:     meta.sessionID,
					SourceIP:      meta.sourceIP,
					SourcePort:    meta.sourcePort,
					ClientVersion: meta.clientVersion,
					EventType:     model.EventCommand,
					Username:      meta.username,
					Command:       cmd,
					Detail:        "shell",
				})
			}

			out, code, shouldExit := shell.Execute(trimmed)
			if out != "" {
				_, _ = io.WriteString(ch, out)
			}
			if shouldExit {
				sendExitStatus(ch, code)
				return
			}
		}

		if err != nil {
			sendExitStatus(ch, 0)
			return
		}
	}
}

func readLineAnyEOL(rawConn net.Conn, reader *bufio.Reader, timeout time.Duration) (string, error) {
	var buf strings.Builder
	for {
		_ = rawConn.SetReadDeadline(time.Now().Add(timeout))
		b, err := reader.ReadByte()
		_ = rawConn.SetReadDeadline(time.Time{})
		if err != nil {
			return buf.String(), err
		}
		if b == '\n' {
			return buf.String(), nil
		}
		if b == '\r' {
			if next, peekErr := reader.Peek(1); peekErr == nil && len(next) == 1 && next[0] == '\n' {
				_, _ = reader.ReadByte()
			}
			return buf.String(), nil
		}
		if buf.Len() < maxLoggedTextLen {
			buf.WriteByte(b)
		}
	}
}

func (s *Server) emitLog(entry model.LogEntry) {
	if s.onLog == nil {
		return
	}
	entry.ID = randomHex(8)
	entry.HoneypotID = s.hp.ID
	entry.HoneypotName = s.hp.Name
	entry.HoneypotType = s.hp.Type
	entry.HoneypotPort = s.hp.Port
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now().UTC()
	}
	s.onLog(entry)
}

func sendExitStatus(ch ssh.Channel, code int) {
	var payload [4]byte
	binary.BigEndian.PutUint32(payload[:], uint32(code))
	_, _ = ch.SendRequest("exit-status", false, payload[:])
}

func parseRemoteAddr(addr net.Addr) (string, int) {
	if addr == nil {
		return "", 0
	}
	host, portStr, err := net.SplitHostPort(addr.String())
	if err != nil {
		return addr.String(), 0
	}
	port, _ := strconv.Atoi(portStr)
	return host, port
}

func sanitizeText(s string, maxLen int) string {
	var sb strings.Builder
	for _, r := range s {
		if r == '\t' || r == ' ' {
			sb.WriteRune(r)
			continue
		}
		if unicode.IsControl(r) {
			continue
		}
		sb.WriteRune(r)
		if sb.Len() >= maxLen {
			break
		}
	}
	return strings.TrimSpace(sb.String())
}

func randomHex(nBytes int) string {
	b := make([]byte, nBytes)
	if _, err := rand.Read(b); err != nil {
		return strconv.FormatInt(time.Now().UnixNano(), 16)
	}
	return hex.EncodeToString(b)
}
